import os
import sys
import base64
import urllib.parse
from playwright.sync_api import sync_playwright

html_template = '''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>{title} - Infographic</title>
<style>
html, body {{ margin: 0; padding: 0; width: 100%; height: 100%; background: {bg}; }}
#container {{ width: 100%; height: 100%; }}
</style>
</head>
<body>
<div id="container"></div>
<script src="/app/vendor/infographic.min.js"></script>
<script>
const infographic = new AntVInfographic.Infographic({{
  container: '#container',
  width: '100%',
  height: '100%',
}});
const syntax = `{syntax}`;
infographic.render(syntax);
document.fonts?.ready.then(() => {{
  infographic.render(syntax);
}}).catch((error) => console.error('Error waiting for fonts to load:', error));
window.infographic = infographic;
</script>
</body>
</html>
'''

sections = []
with open('/app/sections.txt', 'r') as f:
    content = f.read()

for block in content.split('---'):
    block = block.strip()
    if not block:
        continue
    lines = block.split('\n')
    section_name = None
    width = 1200
    height = 400
    bg = '#0b1120'
    syntax_lines = []
    in_syntax = False
    for line in lines:
        if line.startswith('SECTION:'):
            section_name = line.split(':', 1)[1].strip()
        elif line.startswith('WIDTH:'):
            width = int(line.split(':', 1)[1].strip())
        elif line.startswith('HEIGHT:'):
            height = int(line.split(':', 1)[1].strip())
        elif line.startswith('BG:'):
            bg = line.split(':', 1)[1].strip()
        elif line == 'SYNTAX:':
            in_syntax = True
        elif in_syntax:
            syntax_lines.append(line)
    if section_name:
        sections.append({
            'name': section_name,
            'width': width,
            'height': height,
            'bg': bg,
            'syntax': '\n'.join(syntax_lines).strip()
        })

output_dir = '/app/output/sections'
os.makedirs(output_dir, exist_ok=True)

with sync_playwright() as p:
    browser = p.chromium.launch(headless=True)
    for sec in sections:
        html_path = os.path.join(output_dir, f"{sec['name']}.html")
        svg_path = os.path.join(output_dir, f"{sec['name']}.svg")
        html_content = html_template.format(
            title=sec['name'],
            bg=sec['bg'],
            syntax=sec['syntax']
        )
        with open(html_path, 'w') as f:
            f.write(html_content)

        page = browser.new_page(viewport={'width': sec['width'], 'height': sec['height']})
        page.goto(f'file://{html_path}')
        page.wait_for_timeout(3000)
        svg_data_url = page.evaluate('''async () => {
            const infographic = window.infographic;
            if (!infographic) return null;
            return await infographic.toDataURL({ type: 'svg' });
        }''')
        if svg_data_url:
            header, encoded = svg_data_url.split(',', 1)
            if 'base64' in header:
                data = base64.b64decode(encoded)
            else:
                data = urllib.parse.unquote(encoded).encode('utf-8')
            with open(svg_path, 'wb') as f:
                f.write(data)
            print(f"Saved {sec['name']}.svg ({len(data)} bytes)")
        else:
            print(f"No SVG for {sec['name']}")
        page.close()
    browser.close()
